import{_ as a,o as s,c as i,a2 as o}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"开发故障排查","description":"按安装、连接、队列、索引和浏览器症状定位 Ershu 本地开发问题。","frontmatter":{"page_id":"development-troubleshooting","description":"按安装、连接、队列、索引和浏览器症状定位 Ershu 本地开发问题。"},"headers":[],"relativePath":"development/troubleshooting.md","filePath":"development/troubleshooting.md","lastUpdated":1786290726000}'),l={name:"development/troubleshooting.md"};function n(t,e,d,r,p,c){return s(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="开发故障排查" tabindex="-1">开发故障排查 <a class="header-anchor" href="#开发故障排查" aria-label="Permalink to &quot;开发故障排查&quot;">​</a></h1><p>排查 Ershu 时，先确认问题停在哪一层：依赖安装、基础设施、API、Worker、前端，还是某次运行的产物。不要因为一个存活检查通过，就假定整个分析链路都正常。</p><p>本页命令用于诊断，没有声称已经在你的环境中执行成功。</p><h2 id="uv-sync-无法取得-ershu-包" tabindex="-1"><code>uv sync</code> 无法取得 Ershu 包 <a class="header-anchor" href="#uv-sync-无法取得-ershu-包" aria-label="Permalink to &quot;`uv sync` 无法取得 Ershu 包&quot;">​</a></h2><p><strong>常见表现：</strong> 安装停在 Core、API、Worker 或 MCP 的私有 Git 地址，并报告权限、SSH 或仓库访问错误。</p><p><strong>原因：</strong> 当前组合仓库仍从私有开发源取得后端组件，后端组件也仍受私有 Core 依赖限制。公开安装条件尚未完成。</p><p><strong>处理：</strong></p><ol><li>确认账号具有对应 Git 和 SSH 权限。</li><li>保留锁文件，重新检查凭据和主机访问。</li><li>没有权限时停止安装，等待公开包或正式发布说明；不要删除锁文件，也不要换成同名的未知包。</li></ol><p><strong>恢复判据：</strong> <code>uv sync --all-extras --frozen</code> 以退出码 <code>0</code> 结束。仅仅跳过某个组件不算完整组合安装成功。</p><h2 id="前端依赖安装或启动失败" tabindex="-1">前端依赖安装或启动失败 <a class="header-anchor" href="#前端依赖安装或启动失败" aria-label="Permalink to &quot;前端依赖安装或启动失败&quot;">​</a></h2><p><strong>先检查版本：</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>当前前端固定 Node.js 24。成功时，版本输出以 <code>v24</code> 开头，<code>npm ci</code> 以退出码 <code>0</code> 结束。不要用更新锁文件的方式掩盖版本不匹配。</p><p>若 <code>npm run dev</code> 已启动但页面空白，打开浏览器控制台并检查终端中的构建错误。修复后，<code>http://localhost:3000</code> 应进入设置、登录或项目页。</p><h2 id="前端显示网络错误或一直停在加载状态" tabindex="-1">前端显示网络错误或一直停在加载状态 <a class="header-anchor" href="#前端显示网络错误或一直停在加载状态" aria-label="Permalink to &quot;前端显示网络错误或一直停在加载状态&quot;">​</a></h2><p>先直接检查 API：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8000/health</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>无法连接：API 没有启动、端口不同，或被本机网络规则阻止。</li><li>返回状态 <code>ok</code>：API 进程存活，继续检查前端代理。</li></ul><p>前端开发环境默认把 <code>/api</code> 转发到 <code>http://localhost:8000</code>。如果 API 在其他地址，修改 <code>.env.local</code> 的 <code>VITE_DEV_API_PROXY</code> 并重启 <code>npm run dev</code>。</p><p><strong>恢复判据：</strong> 打开前端根地址后，页面能根据数据库状态进入首次管理员设置、登录或项目列表，不再持续显示请求失败。</p><h2 id="health-正常-但项目操作仍失败" tabindex="-1"><code>/health</code> 正常，但项目操作仍失败 <a class="header-anchor" href="#health-正常-但项目操作仍失败" aria-label="Permalink to &quot;`/health` 正常，但项目操作仍失败&quot;">​</a></h2><p><code>/health</code> 和 <code>/api/v1/health</code> 只表示 API 进程存活。依赖检查使用：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8000/api/v1/health/dependencies</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这个响应检查数据库和 Milvus，状态可能是 <code>ok</code> 或 <code>degraded</code>。它不检查 Redis，所以即使返回 <code>ok</code>，仍不能证明登录限流、队列相关连接或 Worker 都正常。</p><p><strong>处理：</strong> 根据响应中的 <code>database</code> 和 <code>milvus</code> 结果检查地址、凭据和服务状态；Redis 与 Worker 需要单独检查。</p><h2 id="运行长时间停在-queued" tabindex="-1">运行长时间停在 <code>queued</code> <a class="header-anchor" href="#运行长时间停在-queued" aria-label="Permalink to &quot;运行长时间停在 `queued`&quot;">​</a></h2><p><strong>最可能的原因：</strong> Worker 没有运行，或 Worker 和 API 没有连接到同一套数据库。</p><p><strong>处理顺序：</strong></p><ol><li>确认 <code>uv run ershu-worker</code> 进程仍在运行。</li><li>确认 API 和 Worker 使用同一份数据库、Redis、Milvus 与相关密钥配置。</li><li>查看 Worker 当前错误，重点检查仓库凭据、分支和模型通道。</li><li>修复根因后再决定取消或重试，不要连续创建相同运行。</li></ol><p><strong>恢复判据：</strong> 运行从 <code>queued</code> 进入 <code>scanning</code>、<code>analyzing</code> 或 <code>finalizing</code>，详情页开始出现新的时间线内容。</p><h2 id="第一次运行不能选择单仓库或增量" tabindex="-1">第一次运行不能选择单仓库或增量 <a class="header-anchor" href="#第一次运行不能选择单仓库或增量" aria-label="Permalink to &quot;第一次运行不能选择单仓库或增量&quot;">​</a></h2><p>这是预期限制，不是前端故障。项目必须先建立覆盖全部活动仓库的完整项目基线。</p><p>选择 <strong>完整项目</strong>（<code>full_project</code>）并保留全部活动仓库。基线成功后，能力接口才可能开放单仓库或增量类型，具体以当前项目返回的选项为准。</p><p><strong>恢复判据：</strong> 第一次完整项目运行可以提交，并出现在运行列表中。</p><h2 id="运行因模型配置失败" tabindex="-1">运行因模型配置失败 <a class="header-anchor" href="#运行因模型配置失败" aria-label="Permalink to &quot;运行因模型配置失败&quot;">​</a></h2><p>仓库分析必须有可用的 LLM 通道。模型名称、API Key 和地址不从 <code>.env</code> 读取。</p><p>进入管理员的模型通道页面，确认：</p><ul><li>至少一个 <code>llm</code> 通道已启用；</li><li>连接或模型测试可用；</li><li>项目或运行选择了有效通道；</li><li>通过非本机地址提交密钥时使用 HTTPS。</li></ul><p><strong>恢复判据：</strong> 新运行不再因缺少 LLM 通道立即失败，并能进入扫描或分析阶段。</p><h2 id="语义搜索不可用-或混合搜索显示降级" tabindex="-1">语义搜索不可用，或混合搜索显示降级 <a class="header-anchor" href="#语义搜索不可用-或混合搜索显示降级" aria-label="Permalink to &quot;语义搜索不可用，或混合搜索显示降级&quot;">​</a></h2><p>先检查最近运行的 <code>search_index_status</code>：</p><ul><li><code>indexed</code>：语义索引已建立；</li><li><code>degraded</code>：部分能力不可用，应阅读警告；</li><li><code>unavailable</code>：当前没有可用语义索引。</li></ul><p>语义搜索不可用时不会悄悄伪装为关键词结果。混合搜索可以明确回退到关键词，并在页面显示降级提示。</p><p><strong>处理：</strong> 确认有独立、已启用的 embedding 通道，运行选择了它，并检查运行警告和 Milvus 依赖状态。</p><p><strong>恢复判据：</strong> 新的完整分析建立索引后，语义查询能够返回结果，页面也不再显示未处理的降级原因。</p><h2 id="docs-没有文档-或问答没有上下文" tabindex="-1">Docs 没有文档，或问答没有上下文 <a class="header-anchor" href="#docs-没有文档-或问答没有上下文" aria-label="Permalink to &quot;Docs 没有文档，或问答没有上下文&quot;">​</a></h2><p>依次检查：</p><ol><li>最近运行是否为 <code>completed</code> 或 <code>completed_with_warnings</code>。</li><li>运行详情是否真的列出生成文档。</li><li>带警告完成时，是否有仓库或文档生成阶段失败。</li><li>问答使用的项目是否正确。</li><li>项目是否有可用模型通道和可检索内容。</li></ol><p>Docs 中的问答始终是项目范围，不会自动缩小到当前文档或章节。回答引用不同仓库并不一定是范围错误。</p><p><strong>恢复判据：</strong> Docs 能打开生成文档；问答返回内容时，引用可以打开对应来源预览。</p><h2 id="登录后写请求被-csrf-或安全策略拒绝" tabindex="-1">登录后写请求被 CSRF 或安全策略拒绝 <a class="header-anchor" href="#登录后写请求被-csrf-或安全策略拒绝" aria-label="Permalink to &quot;登录后写请求被 CSRF 或安全策略拒绝&quot;">​</a></h2><p>本地开发优先使用 <code>localhost</code> 或 <code>127.0.0.1</code>。生产或通过其他主机名访问时必须使用 HTTPS。</p><p>若 HTTPS 在反向代理终止，请检查：</p><ul><li>外部 Host 和 Origin 被原样传递；</li><li><code>X-Forwarded-Proto</code> 是真实的外部协议；</li><li>API 信任实际代理来源；</li><li>Cookie 和允许来源配置与外部地址一致。</li></ul><p>不要通过关闭 CSRF 或安全 Cookie 来让请求通过。</p><p><strong>恢复判据：</strong> 登录可以恢复会话，创建项目、保存模型通道等 Cookie 鉴权写请求不再被判为跨站或非安全请求。</p><h2 id="mcp-客户端连接到了错误端口" tabindex="-1">MCP 客户端连接到了错误端口 <a class="header-anchor" href="#mcp-客户端连接到了错误端口" aria-label="Permalink to &quot;MCP 客户端连接到了错误端口&quot;">​</a></h2><p>同源部署中，<code>/api/</code> 应转发到 API 的 8000 端口，<code>/mcp/</code> 应转发到 MCP 的 8001 端口。不能把 <code>/mcp/</code> 送到 API，也不能在代理时意外删除 MCP 路径前缀。</p><p><strong>恢复判据：</strong> API 页面继续正常工作，MCP 客户端也能通过单独的 <code>/mcp/</code> 地址建立连接。</p><h2 id="已完成运行不再出现实时事件" tabindex="-1">已完成运行不再出现实时事件 <a class="header-anchor" href="#已完成运行不再出现实时事件" aria-label="Permalink to &quot;已完成运行不再出现实时事件&quot;">​</a></h2><p>这是预期行为。活动运行使用快照和游标后的事件；<code>completed</code> 与 <code>completed_with_warnings</code> 直接读取最终结果，不再连接事件流。<code>failed</code> 和 <code>cancelled</code> 也不会继续接收实时事件。</p><p><strong>恢复判据：</strong> 刷新已完成运行后，页面直接显示最终文本、分析块、警告和文档，而不是重新播放早期输出。</p><h2 id="前端检查失败" tabindex="-1">前端检查失败 <a class="header-anchor" href="#前端检查失败" aria-label="Permalink to &quot;前端检查失败&quot;">​</a></h2><p>按失败命令分别处理：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format:check</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ul><li>测试失败：先修正状态逻辑或请求约定，不要删除断言。</li><li><code>lint</code> 失败：同时检查代码规则和 TypeScript 错误。</li><li>格式检查失败：只重新排版本次修改的文件，避免覆盖无关改动。</li><li>构建失败：从第一个构建错误开始处理，不要只看最后一行。</li></ul><p>四条命令都以退出码 <code>0</code> 结束，并且构建生成 <code>dist/</code>，才表示自动检查完成。浏览器中的中英文、主题、窄屏和长任务刷新仍需手工检查。完整的前端修改流程见<a href="./frontend">开发前端</a>。</p>',67)])])}const g=a(l,[["render",n]]);export{u as __pageData,g as default};
